=== FILE: tb_uart_tx_reload_repro.v ===
// Repro for uart_tx: a start pulse while a frame is in flight must be ignored.
// Expected values come from the 8N1 frame definition (start 0, 8 data bits
// LSB first, stop 1, CLKS_PER_BIT cycles each) and from the clause
// "A start pulse while a frame is in flight is ignored."
`timescale 1ns / 1ps
module tb_uart_tx_reload_repro;
    localparam integer CPB = 4;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'h00;
    wire       tx;
    wire       busy;

    uart_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk  (clk),
        .rst  (rst),
        .start(start),
        .data (data),
        .tx   (tx),
        .busy (busy)
    );

    always #5 clk = ~clk;

    reg [8*64-1:0] nonce;
    integer passed = 0;
    integer failed = 0;
    reg     reported = 1'b0;

    reg [7:0] rx_byte;
    reg       rx_framing_ok;
    reg       idle_ok;
    reg       quiet_ok;
    integer   k;
    integer   n;

    task check;
        input              cond;
        input [8*80-1:0]   name;
        begin
            if (cond) begin
                passed = passed + 1;
                $display("PASS: %0s", name);
            end else begin
                failed = failed + 1;
                $display("FAIL: %0s", name);
            end
        end
    endtask

    task finish_run;
        begin
            if (!reported) begin
                reported = 1'b1;
                $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
            end
            $finish;
        end
    endtask

    // Drive a one-cycle start pulse; inputs change on falling edges only.
    task pulse_start;
        input [7:0] value;
        begin
            @(negedge clk);
            start = 1'b1;
            data  = value;
            @(negedge clk);
            start = 1'b0;
            data  = 8'h00;
        end
    endtask

    // Self-timed 8N1 receiver: sync on the start-bit falling edge, then
    // sample mid-bit on falling clock edges.
    task receive_frame;
        begin
            @(negedge tx);
            repeat (CPB / 2) @(negedge clk);
            rx_framing_ok = (tx === 1'b0);
            for (k = 0; k < 8; k = k + 1) begin
                repeat (CPB) @(negedge clk);
                rx_byte[k] = tx;
            end
            repeat (CPB) @(negedge clk);
            rx_framing_ok = rx_framing_ok & (tx === 1'b1);
        end
    endtask

    task wait_idle;
        begin
            idle_ok = 1'b0;
            for (n = 0; n < 4 * CPB && !idle_ok; n = n + 1) begin
                @(negedge clk);
                if (busy === 1'b0 && tx === 1'b1)
                    idle_ok = 1'b1;
            end
        end
    endtask

    task watch_quiet;
        begin
            quiet_ok = 1'b1;
            for (n = 0; n < 3 * 10 * CPB; n = n + 1) begin
                @(negedge clk);
                if (busy !== 1'b0 || tx !== 1'b1)
                    quiet_ok = 1'b0;
            end
        end
    endtask

    initial begin
        nonce = "unset";
        if (!$value$plusargs("NIRMAAN_NONCE=%s", nonce))
            if (!$value$plusargs("nirmaan_nonce=%s", nonce))
                if (!$value$plusargs("NONCE=%s", nonce))
                    if (!$value$plusargs("nonce=%s", nonce))
                        nonce = "unset";

        repeat (4) @(negedge clk);
        rst = 1'b0;
        repeat (2) @(negedge clk);

        // Check 1: an undisturbed frame is transmitted correctly.
        fork
            pulse_start(8'hA5);
            receive_frame;
        join
        check(rx_framing_ok && (rx_byte === 8'hA5),
              "baseline frame carries 8'hA5 as 8N1");

        // Check 2: the transmitter returns to idle.
        wait_idle;
        check(idle_ok, "line idle and busy low after baseline frame");

        // Check 3: a start pulse during data bit 1 must not change the frame.
        fork
            begin
                pulse_start(8'hC3);
                repeat (9) @(negedge clk);
                pulse_start(8'h3C);
            end
            receive_frame;
        join
        check(rx_framing_ok && (rx_byte === 8'hC3),
              "start pulse during frame ignored: frame still carries 8'hC3");
        if (rx_byte !== 8'hC3)
            $display("INFO: received byte 8'h%02h, expected 8'hC3", rx_byte);

        // Check 4: the ignored pulse does not launch a second frame.
        wait_idle;
        watch_quiet;
        check(idle_ok && quiet_ok,
              "ignored start pulse does not launch a second frame");

        finish_run;
    end

    initial begin
        #100000;
        failed = failed + 1;
        $display("FAIL: watchdog timeout");
        finish_run;
    end
endmodule
=== END FILE ===
